import requests
terms='(amyotrophic lateral sclerosis[Title/Abstract] OR ALS[Title/Abstract]) AND (noninvasive ventilation[Title/Abstract] OR non-invasive ventilation[Title/Abstract] OR NIV[Title/Abstract]) AND (pain threshold[Title/Abstract] OR pain sensitivity[Title/Abstract] OR dyspnea[Title/Abstract] OR dyspnoea[Title/Abstract])'
r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':terms,'retmode':'json','retmax':20},timeout=20)
r.raise_for_status(); ids=r.json()['esearchresult']['idlist']; print('PubMed IDs:',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20); x.raise_for_status(); data=x.json()['result'];
 for i in ids:
  d=data[i]; print(i, d.get('title'), d.get('pubdate'))
else:
 print('No records for combined query')
print('Search log: direct PubMed E-utilities query completed.')

